import{c as t,Q as r,j as o,m as n}from"./chunks/framework.DoOjWOm2.js";const p=JSON.parse('{"title":"Roku Channel","description":"","frontmatter":{},"headers":[],"relativePath":"clients/roku.md","filePath":"clients/roku.md"}'),a={name:"clients/roku.md"};function s(i,e,l,h,c,d){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="roku-channel" tabindex="-1">Roku Channel <a class="header-anchor" href="#roku-channel" aria-label="Permalink to &quot;Roku Channel&quot;">​</a></h1><p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.13 <strong>Since:</strong> 0.18.0</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The Phlix channel for Roku brings your media library to any Roku streaming device. Add the channel from the Roku Channel Store, open it, enter your server URL (or sign in with Hub), and start streaming. Works on all Roku models running OS 10 or later.</p></div><h2 id="install-store-links" tabindex="-1">Install / Store Links <a class="header-anchor" href="#install-store-links" aria-label="Permalink to &quot;Install / Store Links&quot;">​</a></h2><ul><li><strong>Roku Channel Store:</strong> Search for <strong>Phlix</strong> on your Roku device or at <a href="https://channel.roku.com" target="_blank" rel="noreferrer">channel.roku.com</a></li><li><strong>Developer sideload (.ipk):</strong> <a href="https://github.com/detain/phlix-roku-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-roku-client/releases</a> — for beta testing and development devices only</li></ul><h2 id="platform-specific-install-steps" tabindex="-1">Platform-Specific Install Steps <a class="header-anchor" href="#platform-specific-install-steps" aria-label="Permalink to &quot;Platform-Specific Install Steps&quot;">​</a></h2><h3 id="add-the-official-channel-recommended" tabindex="-1">Add the Official Channel (Recommended) <a class="header-anchor" href="#add-the-official-channel-recommended" aria-label="Permalink to &quot;Add the Official Channel (Recommended)&quot;">​</a></h3><ol><li>From the Roku home screen, navigate to <strong>Streaming Channels → Search Channels</strong>.</li><li>Type <strong>Phlix</strong> and select the Phlix channel from the results.</li><li>Click <strong>Add Channel</strong> and confirm. The channel appears on your home screen.</li><li>Open <strong>Phlix</strong> from your channel list.</li></ol><h3 id="developer-sideload-beta-testing-only" tabindex="-1">Developer Sideload (Beta / Testing Only) <a class="header-anchor" href="#developer-sideload-beta-testing-only" aria-label="Permalink to &quot;Developer Sideload (Beta / Testing Only)&quot;">​</a></h3><ol><li>Download the latest <code>.ipk</code> package from <a href="https://github.com/detain/phlix-roku-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-roku-client/releases</a>.</li><li>Set up your Roku device for development at <a href="https://developer.roku.com" target="_blank" rel="noreferrer">developer.roku.com</a> — create a developer account and register your device.</li><li>Use the <strong>Roku Developer Application Loader (RDA)</strong> to install:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rokudev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Phlix-1.0.0.ipk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.1.x</span></span></code></pre></div></li><li>The channel appears in <strong>My Channels</strong> on the home screen.</li></ol><h3 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h3><p>On first open, the Phlix channel shows a server URL entry screen:</p><ol><li>Enter your server&#39;s address: <ul><li><strong>Local:</strong> <code>http://192.168.1.100:32400</code> (replace with your server&#39;s LAN IP)</li><li><strong>Remote:</strong> your server&#39;s public domain if you have remote access configured</li></ul></li><li>Press <strong>Connect</strong> on your remote.</li><li>The URL is saved to persistent storage and remembered on subsequent launches.</li></ol><h2 id="hub-connection" tabindex="-1">Hub Connection <a class="header-anchor" href="#hub-connection" aria-label="Permalink to &quot;Hub Connection&quot;">​</a></h2><ol><li>In the Phlix channel, go to <strong>Settings</strong> (gear icon).</li><li>Select <strong>Hub Login</strong>.</li><li>Enter your Hub URL (e.g., <code>https://hub.phlix.example.com</code>) and press <strong>OK</strong>.</li><li>Enter your Hub username and password on the on-screen keyboard.</li><li>After authentication, the Hub auto-populates your server URL if you have a server claimed. No manual entry required.</li></ol><p>Hub login also enables remote playback when you are away from home — the Hub relay handles the connection without any router configuration.</p><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="server-url-is-wrong-or-mistyped" tabindex="-1">Server URL is wrong or mistyped <a class="header-anchor" href="#server-url-is-wrong-or-mistyped" aria-label="Permalink to &quot;Server URL is wrong or mistyped&quot;">​</a></h3><p><strong>Symptom:</strong> Immediately after entering the server URL and pressing Connect, the channel displays &quot;Unable to reach server.&quot;</p><p><strong>Fix:</strong> Verify the URL protocol — <code>http://</code> and <code>https://</code> are different. Confirm the port number is correct (default is <code>32400</code>). Try using the direct LAN IP address of your server. If you are traveling, you need either a Hub relay URL or a configured VPN to reach your server remotely.</p><h3 id="roku-not-on-the-same-network-as-the-server" tabindex="-1">Roku not on the same network as the server <a class="header-anchor" href="#roku-not-on-the-same-network-as-the-server" aria-label="Permalink to &quot;Roku not on the same network as the server&quot;">​</a></h3><p><strong>Symptom:</strong> Your phone or computer can connect to the server fine, but the Roku channel shows &quot;Server unreachable&quot; despite a correct URL.</p><p><strong>Fix:</strong> Some Roku models default to a &quot;linked&quot; or guest network that isolates them from other devices. In your router&#39;s admin panel, verify the Roku is on the same SSID as your server. Check that the router does not have <strong>Client Isolation</strong> or <strong>AP Isolation</strong> enabled. As a workaround, try connecting the server via Ethernet to the router instead of Wi-Fi.</p><h3 id="channel-store-version-vs-dev-channel-version-mismatch" tabindex="-1">Channel store version vs. dev channel version mismatch <a class="header-anchor" href="#channel-store-version-vs-dev-channel-version-mismatch" aria-label="Permalink to &quot;Channel store version vs. dev channel version mismatch&quot;">​</a></h3><p><strong>Symptom:</strong> The version of Phlix on the Channel Store behaves differently from the version you sideloaded for testing.</p><p><strong>Fix:</strong> Report the discrepancy at <a href="https://github.com/detain/phlix-roku-client/issues" target="_blank" rel="noreferrer">github.com/detain/phlix-roku-client/issues</a>. For production use, always rely on the Channel Store version — it has passed Roku&#39;s certification process. Dev sideloads are for beta testing only.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./tizen.html">Tizen</a> — Samsung Smart TV app</li><li><a href="./windows.html">Windows client</a> — desktop client with additional features</li><li><a href="./../first-run.html">First-run wizard</a> — configure your libraries after connecting a client</li></ul>',28)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
